import React, { useEffect, useState, useRef } from 'react';
import * as openpgp from 'openpgp';
import { v4 as uuidv4 } from 'uuid';
import { generateKeys, encryptMessage, decryptMessage, storePrivateKey, retrievePrivateKey } from '../utils/crypto';

const Chat = () => {
  const [messages, setMessages] = useState([]); // Сообщения чата
  const [input, setInput] = useState(''); // Поле ввода
  const [keys, setKeys] = useState({ publicKey: null, recipientPublicKey: null }); // Ключи для шифрования

  const privateKeyRef = useRef(null); // Ссылка на приватный ключ
  const wsRef = useRef(null); // Ссылка на WebSocket

  useEffect(() => {
    const initChat = async () => {
      try {
        // Получаем clientId из localStorage или создаём новый
        let clientId = localStorage.getItem('clientId');
        if (!clientId) {
          clientId = uuidv4();
          localStorage.setItem('clientId', clientId);
          console.log('Создан новый clientId:', clientId);
        } else {
          console.log('Используется существующий clientId:', clientId);
        }

        // Генерация или загрузка ключей
        let privateKey = await retrievePrivateKey();
        let publicKey;

        if (!privateKey) {
          const generatedKeys = await generateKeys();
          privateKey = generatedKeys.privateKey;
          publicKey = generatedKeys.publicKey;
          await storePrivateKey(privateKey);
          console.log('Ключи сгенерированы и сохранены');
        } else {
          const extractedKey = await openpgp.readKey({ armoredKey: privateKey });
          publicKey = extractedKey.toPublic().armor();
          console.log('Приватный ключ загружен из хранилища');
        }

        privateKeyRef.current = privateKey;
        setKeys((prevKeys) => ({ ...prevKeys, publicKey }));
        
        if (!wsRef.current) {  // Проверяем, нет ли уже активного соединения
          // Инициализация WebSocket
          console.log('Инициализация WebSocket-соединения...');
          wsRef.current = new WebSocket('ws://localhost:8080');
        }
        wsRef.current.onopen = () => {
          console.log('WebSocket подключен');
          if (clientId && publicKey) {
            wsRef.current.send(
              JSON.stringify({
                type: 'key_exchange',
                publicKey,
                clientId,
              })
            );
            console.log('Публичный ключ и clientId отправлены на сервер');
          } else {
            console.error('Отсутствует clientId или publicKey');
          }
        };

        wsRef.current.onmessage = async (event) => {
          const data = JSON.parse(event.data);
          console.log('Получено сообщение от сервера:', data);

          if (data.type === 'key_exchange' && data.publicKey) {
            setKeys((prevKeys) => ({ ...prevKeys, recipientPublicKey: data.publicKey }));
            console.log('Получен публичный ключ другого клиента:', data.publicKey);
          } else if (data.type === 'message') {
            try {
              const decryptedMessage = await decryptMessage(data.encryptedMessage, privateKeyRef.current);
              setMessages((prev) => [...prev, { userId: data.userId, text: decryptedMessage }]);
            } catch (err) {
              console.error('Ошибка расшифровки сообщения:', err);
            }
          }
        };

        wsRef.current.onerror = (err) => {
          console.error('WebSocket error:', err);
        };

        wsRef.current.onclose = (event) => {
          console.log('WebSocket connection closed', event);
          wsRef.current = null;
        };
      } catch (err) {
        console.error('Ошибка инициализации чата:', err);
      }
    };

    initChat();

    return () => {
      if (wsRef.current) {
        console.log('Закрытие WebSocket-соединения при размонтировании.');
        wsRef.current.close();
      }
    };
  }, []);

  const sendMessage = async (message) => {
    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
      console.error('WebSocket не подключен');
      return;
    }

    if (!keys.recipientPublicKey) {
      console.error('Публичный ключ получателя отсутствует');
      return;
    }

    try {
      const encryptedMessage = await encryptMessage(message, keys.recipientPublicKey);
      wsRef.current.send(
        JSON.stringify({
          type: 'message',
          encryptedMessage,
          clientId: localStorage.getItem('clientId'),
        })
      );
      setMessages((prev) => [...prev, { userId: 'Вы', text: message }]);
      setInput('');
    } catch (err) {
      console.error('Ошибка отправки сообщения:', err);
    }
  };

  return (
    <div>
      <h1>Anonymous Chat</h1>
      {!keys.recipientPublicKey && (
        <p style={{ color: 'red' }}>
          Ожидание публичного ключа другого клиента. Подключите второго клиента для начала общения.
        </p>
      )}
      <div>
        {messages.map((msg, index) => (
          <p key={index}>
            <strong>{msg.userId}:</strong> {msg.text}
            {console.log(msg)}

          </p>
        ))}
      </div>
      <input
        type="text"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Введите сообщение..."
      />
      <button onClick={() => sendMessage(input)} disabled={!keys.recipientPublicKey}>
        Отправить
      </button>
    </div>
  );
};

export default Chat;
